export type IntelligenceCenterTab = 'overview' | 'sources' | 'incidents' | 'cases' | 'watchlists' | 'geofences' | 'rules' | 'alerts' | 'search' | 'ai' | 'workspaces' | 'settings' | 'diagnostics';
