type SourceHealth = { source_id: string; provider: string; state: string; last_success_at?: string | null; latency_ms?: number | null; record_count?: number; reliability?: number; last_error?: string | null; cache_age_seconds?: number | null; quarantined?: boolean; quarantine?: { reason?: string; quarantine_kind?: string; quarantined_at?: string; until_epoch?: number; manual?: boolean } };
type IntelCase = { id: string; title: string; status: string; priority: string; updated_at: string; tags?: string[] };
type IntelAlert = { id: string; title: string; severity: string; status: string; created_at: string; detail?: string };
type WatchItem = { id: string; entity_type: string; value: string; label?: string | null; enabled: boolean; created_at: string };
type Geofence = { id:string; name:string; polygon:Array<{lat:number;lng:number}>; severity:string; enabled:boolean; entity_types:string[]; cooldown_seconds:number; created_at:string };
type IntelRule = { id: string; name: string; severity: string; enabled: boolean; cooldown_seconds: number; conditions: { mode?: string; items?: Array<Record<string, unknown>> }; last_triggered_at?: string | null; created_at: string };
type Incident = { id: string; title: string; summary: string; severity: string; confidence: number; status: string; last_seen: string; source_ids?: string[] };
type SearchHit = { id: string; kind: string; title: string; body_preview?: string; score: number; updated_at: string };
type RuntimePreferences = { profile: 'low' | 'balanced' | 'performance' | 'maximum'; offline_mode: boolean; metered_network: boolean; max_background_jobs: number; map_marker_budget: number; history_retention_days: number };
type VaultStatus = { protected_by_local_custody: boolean; keys: string[]; count: number };
type IntegrationReadinessItem = { id:string; name:string; category:string; url?:string|null; state:string; records:number; last_success_at?:string|null; mode:string; refreshable:boolean; note?:string; configured:boolean; has_key:boolean; env_key?:string|null };
type IntegrationReadiness = { ok:boolean; counts:Record<string,number>; integrations:IntegrationReadinessItem[]; capabilities:Array<{id:string;name:string;state:string;detail:string}> };
type WorkspacePreset = { id:string; name:string; layout:Record<string, unknown>; is_default:boolean; created_at:string; updated_at:string };
type IntelligenceCenterPanelProps = { onClose: () => void; initialTab?: IntelligenceCenterTab };

const tone: Record<string, string> = {
  live: 'text-emerald-300 border-emerald-500/30 bg-emerald-950/20', stale: 'text-amber-300 border-amber-500/30 bg-amber-950/20', degraded: 'text-orange-300 border-orange-500/30 bg-orange-950/20', error: 'text-red-300 border-red-500/30 bg-red-950/20', rate_limited: 'text-fuchsia-300 border-fuchsia-500/30 bg-fuchsia-950/20', auth_required: 'text-yellow-200 border-yellow-500/30 bg-yellow-950/20', disabled: 'text-slate-500 border-slate-700 bg-black/20', unknown: 'text-slate-300 border-slate-600/30 bg-slate-950/20',
};

async function apiJson(path: string, init?: RequestInit) {
  const response = await fetch(path, { cache: 'no-store', ...init, headers: { 'Content-Type': 'application/json', ...(init?.headers || {}) } });
  const data = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(data?.detail || `İstek başarısız oldu (${response.status})`);
  return data;
}

async function downloadViaApi(path: string, filename: string) {
  const response = await fetch(path, { cache: 'no-store' });
  if (!response.ok) throw new Error(`İndirme başarısız oldu (${response.status})`);
  const blob = await response.blob();
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement('a'); anchor.href = url; anchor.download = filename; document.body.appendChild(anchor); anchor.click(); anchor.remove();
  setTimeout(() => URL.revokeObjectURL(url), 5000);
}

const defaultPrefs: RuntimePreferences = { profile: 'balanced', offline_mode: false, metered_network: false, max_background_jobs: 4, map_marker_budget: 25000, history_retention_days: 30 };

