  const [geofenceName,setGeofenceName]=useState(''); const [geofencePoints,setGeofencePoints]=useState(''); const [geofenceSeverity,setGeofenceSeverity]=useState('watch'); const [geofenceTypes,setGeofenceTypes]=useState('');
